export interface HelpTopic {
  id: string
  title: string
  keywords: string[]
  answer: string[]
  related: string[]
}

export function getHelpTopicCategory(topic: HelpTopic) {
  if (topic.id.startsWith('links-')) return 'קישורים'
  if (topic.id.startsWith('color-')) return 'צבע'
  if (topic.id.startsWith('gradient-')) return 'מעבר צבע'
  if (topic.id.startsWith('swatches-')) return 'דוגמיות'
  if (topic.id.startsWith('layers-')) return 'לשונית שכבות'
  if (topic.id === 'file-export') return 'תפריט קובץ'
  if (topic.id === 'export-pdf' || topic.id.startsWith('pdf-')) return 'קובץ · PDF'
  if (topic.id === 'export-png' || topic.id === 'png-current-page') return 'קובץ · PNG'
  if (topic.id === 'png-selection') return 'PNG · בחירת אובייקטים'
  if (topic.id.startsWith('pages-') || topic.id === 'pages-panel') return 'לוח עמודים'
  if (topic.id.startsWith('page-master-') || topic.id === 'page-masters') return 'עמודי אב'
  if (topic.id.startsWith('page-number-') || topic.id.startsWith('page-section-')) return 'מספור עמודים'
  if (topic.id.startsWith('page-running-')) return 'כותרות משתנות'
  if (/^page-(tool|size|margins)/.test(topic.id)) return 'כלי עמוד'
  if (/^(page-settings|page-text-frames|page-layout)/.test(topic.id) || ['page-count', 'pages-per-row', 'facing-pages'].includes(topic.id)) return 'הגדרות עמודים'
  if (topic.id.startsWith('table-') || topic.id === 'properties-table') return 'טבלאות'
  if (topic.id.startsWith('book-')) return 'ספרים'
  if (topic.id.startsWith('properties-')) return 'חלונית מאפיינים'
  if (topic.id.startsWith('paragraph-')) return 'פסקאות וסגנונות'
  if (topic.id.startsWith('character-style') || topic.id === 'character-styles') return 'סגנונות תו'
  if (topic.id.startsWith('document-') || ['new-document', 'open-file', 'custom-size', 'binding-direction', 'text-frames'].includes(topic.id)) return 'מסמך'
  if (topic.id === 'image-background-removal') return 'תמונות'
  if (topic.id === 'bleed-slug') return 'הגדרות הדפסה'
  return 'כללי'
}

